def _active_diagnostic_preview(data: dict[str, bytes]) -> str | None:
    """Choose retention priority from recorded state, never image authority."""
    def object_member(name: str, fallback: Any = None) -> dict:
        try:
            value = json.loads(data[name]) if name in data else fallback
        except (ValueError, TypeError):
            value = None
        return value if isinstance(value, dict) else {}

    report = object_member("diagnostic-report.json")
    runtime = report.get("runtime")
    runtime = runtime if isinstance(runtime, dict) else {}
    heart = report.get("heart_sender")
    heart = heart if isinstance(heart, dict) else {}

    def active(state: dict, checkpoint: dict) -> bool:
        status = checkpoint.get("status")
        if isinstance(status, str) and status in {"reset", "completed", "stopped", "archived"}:
            return False
        desired = state.get("desired_state")
        return isinstance(desired, str) and desired in {"running", "paused"} or (
            desired is None and status == "active")

    universal_active = active(object_member("state/controller-state.json", runtime.get("controller_state")),
                              object_member("state/checkpoint.json", runtime.get("checkpoint")))
    heart_active = active(object_member("heart-sender/state.json", heart.get("state")),
                          object_member("heart-sender/checkpoint.json", heart.get("checkpoint")))
    if heart_active and not universal_active and "heart-sender/latest-frame.jpg" in data:
        return "heart-sender/latest-frame.jpg"
    binding = runtime.get("active_review_witness")
    bound_review = isinstance(binding, dict) and binding.get("included") is True and binding.get("sha256_matches") is True
    if "images/active-review-witness.png" in data and (bound_review or not report):
        return "images/active-review-witness.png"
    if "images/latest-frame.jpg" in data:
        return "images/latest-frame.jpg"
    if heart_active and "heart-sender/latest-frame.jpg" in data:
        return "heart-sender/latest-frame.jpg"
    return None

